package com.emily.music
import android.view.*
import android.webkit.WebView
import androidx.compose.ui.test.junit4.createAndroidComposeRule
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.*
import org.junit.Assert.*
import java.util.concurrent.*

class MusicYouTubeUiDeviceTest {
 @get:Rule val compose=createAndroidComposeRule<MainActivity>()
 @Test fun playlistPreviewFiltersAndSaveBeforeDownload() {
  org.junit.Assume.assumeTrue(MusicCloud.locallyApproved(compose.activity))
  compose.activity.runOnUiThread {compose.activity.window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)}
  fun find(v:View):WebView?=when(v){is WebView->v;is ViewGroup->(0 until v.childCount).firstNotNullOfOrNull{find(v.getChildAt(it))};else->null}
  fun js(code:String):String {val latch=CountDownLatch(1);var value="null";compose.activity.runOnUiThread{find(compose.activity.window.decorView)?.evaluateJavascript(code){value=it;latch.countDown()}?:latch.countDown()};assertTrue(latch.await(5,TimeUnit.SECONDS));return value}
  for(i in 0..50){compose.waitForIdle();if(js("!!window.YouTubePlaylists&&!!window.EmilyMusic&&!!document.getElementById('modal-player')&&!document.getElementById('modal-player').hidden&&!EmilyMusic.polling")=="true")break;Thread.sleep(200)}
  assertEquals("true",js("!!window.YouTubePlaylists"))
  val script="""
   (()=>{window.youtubeTest='running';const historyKey='emily-music-searches:'+new URLSearchParams(location.search).get('account');const savedHistory=localStorage.getItem(historyKey);const old={play:Player.tocar,queue:Player.playlist,index:Player.indice,current:Player._faixaAtual,origin:Player._playlistAtivaSalva,fav:Player._filaFavoritas,hist:Player._historico,lib:_playlistsGeral,load:carregarGeral,call:musicImportCall,tenta,offline:EmilyMusic.offline,poll:EmilyMusic.pollOffline,prepare:EmilyMusic.prepareVisible,state:window.musicState,view:EmilyMusic.view,tab:EmilyMusic.tab,results:EmilyMusic.searchResults,query:EmilyMusic.searchQuery,input:document.getElementById('pl-query').value};
   window.youtubeCleanup=()=>{Player.tocar=old.play;Player.playlist=old.queue;Player.indice=old.index;Player._faixaAtual=old.current;Player._playlistAtivaSalva=old.origin;Player._filaFavoritas=old.fav;Player._historico=old.hist;if(savedHistory===null)localStorage.removeItem(historyKey);else localStorage.setItem(historyKey,savedHistory);YouTubePlaylists.back();document.querySelector('.music-add-menu')?.remove();_playlistsGeral=old.lib;carregarGeral=old.load;musicImportCall=old.call;tenta=old.tenta;EmilyMusic.offline=old.offline;EmilyMusic.pollOffline=old.poll;EmilyMusic.prepareVisible=old.prepare;window.musicState=old.state;EmilyMusic.searchResults=old.results;EmilyMusic.searchQuery=old.query;document.getElementById('pl-query').value=old.input;EmilyMusic.view=old.view;EmilyMusic.go(old.tab);};
   const assert=(v,msg)=>{if(!v)throw Error(msg);};const m={video_id:'aaaaaaaaaaa',titulo:'Fixture low views',artist:'Artist',views:10,duration:180,thumb:Player._faixaAtual?.thumb||''};const other={...m,video_id:'bbbbbbbbbbb',titulo:'Fixture high views',views:1000};const list={type:'playlist',playlist_id:'PL1234567890abcdefghij',titulo:'Fixture playlist',artist:'Artist',count:30,thumb:m.thumb,url:'https://www.youtube.com/playlist?list=PL1234567890abcdefghij'};const tracks=Array.from({length:30},(_,n)=>({...m,video_id:String(n).padStart(11,'0'),titulo:'Fixture song '+n}));const searchTracks=[m,other,...tracks.slice(0,16)];let downloaded=false,commits=0;
   _playlistsGeral={playlists:{default:{musicas:[]}},favoritos:{},ativa:'default'};carregarGeral=async()=>{};window.musicState=()=>{};Player.tocar=n=>{Player.indice=n;Player._faixaAtual=Player.playlist[n];MusicMobile.update();};EmilyMusic.prepareVisible=()=>{};EmilyMusic.pollOffline=async()=>{};EmilyMusic.offline={online:true,faixas:{}};
   tenta=async(method,...args)=>{if(method==='music_offline_baixar'){assert(_playlistsGeral.playlists['Fixture playlist'],'download before saving');assert(args[0].length===30,'incomplete download');downloaded=true;return {enfileiradas:30};}return false;};
   musicImportCall=async(method,...args)=>{if(method==='playlist_buscar_preview')return {data:{resultados:args[1]==='videos'?searchTracks:[...searchTracks,list]}};if(method==='music_import_preview')return {data:{name:list.titulo,tracks,cover:m.thumb,uploader:'Artist',unavailable:2}};if(method==='music_import_commit'){commits++;assert(args[5]===list.playlist_id,'identity lost');_playlistsGeral.playlists['Fixture playlist']={musicas:tracks,foto:m.thumb,youtube_id:list.playlist_id};return {data:{ok:true,name:'Fixture playlist'}};}return {error:'Unexpected '+method};};
   (async()=>{try{for(const q of ['One','Two','Three','Four'])EmilyMusic.rememberSearch(q);assert(JSON.stringify(EmilyMusic.history())===JSON.stringify(['Four','Three','Two']),'history maximum three/order');await EmilyMusic.search('Fixture search');assert(document.querySelector('.youtube-playlist-row'),'playlist missing');assert(!document.querySelector('#pl-preview button.music-download'),'search download button still present');assert(!document.querySelector('#pl-preview .music-search-play small').textContent.includes('visualizações'),'view counts visible');const container=document.createElement('div');EmilyMusic.downloadButton(m,container);assert(!container.children.length,'unsaved focus download allowed');
   [...document.querySelectorAll('.youtube-search-filters button')].find(b=>b.textContent==='Mais vistas').click();await new Promise(r=>setTimeout(r,100));assert(document.querySelector('#pl-preview .music-search-play strong').textContent==='Fixture high views','views sorting');
   const content=document.querySelector('.emusic-content');content.scrollTop=80;const before=content.scrollTop;await YouTubePlaylists.open(list);const d=document.getElementById('youtube-playlist-preview');assert(!d.hidden&&d.tagName==='SECTION'&&EmilyMusic.tab==='youtube','full page did not open');assert(d.querySelectorAll('.music-search-row').length===30,'tracks missing');assert(!d.querySelector('button.music-download'),'preview downloads bypass library');d.querySelector('.music-search-play').click();assert(Player.playlist.length===30&&Player._faixaAtual.source_title==='Fixture playlist'&&!Player._faixaAtual.autoplay,'playlist source/queue lost');assert(document.getElementById('mobile-now-source').textContent==='Fixture playlist','source label wrong');const sc=content;assert(sc.scrollHeight>sc.clientHeight,'preview cannot scroll');sc.scrollTop=sc.scrollHeight;assert(sc.scrollTop>0,'scroll refused');const add=d.querySelector('.music-search-add');add.click();assert(document.querySelector('.music-add-menu[open]'),'copy menu missing');document.querySelector('.music-add-menu button').click();
   [...d.querySelectorAll('.youtube-preview-actions button')].find(b=>b.textContent.includes('Baixar')).click();await new Promise(r=>setTimeout(r,150));assert(commits===1&&downloaded,'save then download failed');assert(d.querySelector('h1').textContent==='Fixture playlist','playlist title lost');await Promise.all(d.getAnimations().filter(a=>a.effect?.getComputedTiming().iterations!==Infinity).map(a=>a.finished.catch(()=>{})));await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));sc.scrollTop=0;const rect=d.getBoundingClientRect();assert(rect.left>=0&&rect.right<=innerWidth+1,'page cropped');assert(MusicMobile.back(),'back not handled');assert(EmilyMusic.tab==='busca'&&document.getElementById('pl-query').value==='Fixture search','search not restored');assert(Math.abs(content.scrollTop-before)<2,'search scroll not restored');EmilyMusic.playSingle(other);assert(Player.playlist.length===18&&Player.playlist[Player.indice].video_id===other.video_id&&Player.playlist.every(t=>t.autoplay&&t.autoplay_session),'search continuation not seeded');await YouTubePlaylists.open(list);window.youtubeTest='ok';}catch(e){window.youtubeTest=e.message;}})();return true;})()
  """.trimIndent()
  try {assertEquals("true",js(script));var result="running";for(n in 0..100){result=js("window.youtubeTest").trim('"');if(result!="running")break;Thread.sleep(150)};assertEquals("ok",result);Thread.sleep(1000)
   InstrumentationRegistry.getInstrumentation().uiAutomation.takeScreenshot()?.let {bitmap->java.io.File(compose.activity.cacheDir,"youtube-preview.png").outputStream().use{bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,it)}}
  }finally{js("window.youtubeCleanup?.();true")}
 }
}
